// The Gemini models to use, both on the free tier and both always Google's newest of their kind. Lite answers in
// seconds; when it is busy, RankReel asks again and the bigger Flash model answers instead.
const MODELS = ['gemini-flash-lite-latest', 'gemini-flash-latest'];

const ask = $json.body ?? {};
const attempt = Math.min(Math.max(Math.floor(Number(ask.attempt) || 0), 0), MODELS.length - 1);
const model = MODELS[attempt];
// RankReel checks that this workflow is on without spending any of the free Gemini requests.
if (ask.ping) return [{ json: { ping: true, models: MODELS.length } }];

// Thinking makes Gemini slower and these short jobs need little of it. Only the Lite model can go down to minimal.
const thinkingConfig = { thinkingLevel: model.includes('lite') ? 'minimal' : 'low' };
const generationConfig = { temperature: typeof ask.temperature === 'number' ? ask.temperature : 0.8, thinkingConfig };
if (ask.schema) {
  generationConfig.responseMimeType = 'application/json';
  generationConfig.responseJsonSchema = ask.schema;
}
const request = {
  contents: [{ role: 'user', parts: [{ text: String(ask.prompt ?? '') }] }],
  generationConfig,
};
if (ask.system) request.systemInstruction = { parts: [{ text: String(ask.system) }] };
return [{ json: { ping: false, model, request } }];

const reply = $json;
if (reply.error) {
  const error = reply.error;
  const detail = typeof error === 'string' ? error : [error.message, error.description].filter(Boolean).join(' ');
  const used = error.code === 429 || /quota|exhausted|rate/i.test(detail);
  // A busy model often has room again a moment later, or another model can answer instead.
  const busy = error.code === 503 || /overloaded|high demand|unavailable/i.test(detail);
  return [{
    json: {
      status: used ? 429 : busy ? 503 : 502,
      busy,
      error: used
        ? 'Gemini’s free limit is used up for now. Wait a minute and ask again, or try tomorrow.'
        : busy
          ? 'Gemini is very busy right now. Wait a minute and ask again.'
          : `Gemini did not answer: ${detail || 'no reason given'}`,
    },
  }];
}
const candidate = reply.candidates?.[0];
// Thinking models also send their working out; only the answer is kept.
const text = (candidate?.content?.parts ?? []).filter((part) => !part.thought).map((part) => part.text ?? '').join('');
if (!text) {
  const why = candidate?.finishReason ?? reply.promptFeedback?.blockReason;
  return [{ json: { status: 502, error: `Gemini gave no answer${why ? ` (${why})` : ''}. Ask again.` } }];
}
return [{ json: { status: 200, model: reply.modelVersion, text } }];
